import json
import re

def _s(v):
    return '' if v is None else str(v).strip()

def _num(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        try:
            return float(v)
        except Exception:
            return None
    t = _s(v).replace(' ', '')
    if not t:
        return None
    if ',' in t and '.' in t:
        if t.rfind(',') > t.rfind('.'):
            t = t.replace('.', '').replace(',', '.')
        else:
            t = t.replace(',', '')
    elif ',' in t:
        t = t.replace(',', '.')
    try:
        return float(t)
    except Exception:
        return None

def _fmt(v):
    n = _num(v)
    if n is None:
        return _s(v)
    try:
        s = '%.2f' % n
    except Exception:
        return _s(v)
    whole, _, frac = s.partition('.')
    neg = whole.startswith('-')
    if neg:
        whole = whole[1:]
    groups = []
    while len(whole) > 3:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    groups.insert(0, whole or '0')
    out = '.'.join(groups) + ',' + frac
    return ('-' + out) if neg else out

def _true(v):
    return _s(v).lower() in ('true', '1', 'yes', 'evet', 'ok', 'success', 'dogru')

def _text(v):
    if isinstance(v, dict):
        for k in ('text', 'name', 'title', 'value', 'label', 'ad', 'adi'):
            if _s(v.get(k)):
                return _s(v.get(k))
        return ''
    if isinstance(v, list):
        return ', '.join(x for x in (_text(i) for i in v) if x)
    return _s(v)

def _walk(obj, prefix, out):
    if isinstance(obj, dict):
        for k in obj:
            kk = str(k)
            _walk(obj[k], (prefix + '.' + kk) if prefix else kk, out)
    elif isinstance(obj, list):
        i = 0
        while i < len(obj):
            _walk(obj[i], prefix, out)
            i += 1
    else:
        out.append((prefix.lower(), obj))

def _dicts(obj, out):
    if isinstance(obj, dict):
        out.append(obj)
        for k in obj:
            _dicts(obj[k], out)
    elif isinstance(obj, list):
        i = 0
        while i < len(obj):
            _dicts(obj[i], out)
            i += 1

def _dicts_of(obj):
    out = []
    try:
        _dicts(obj, out)
    except Exception:
        pass
    return out

CUR_CODES = [['try', 'TRY'], ['tl', 'TRY'], ['lira', 'TRY'], ['₺', 'TRY'], ['usd', 'USD'], ['dolar', 'USD'], ['dollar', 'USD'], ['$', 'USD'], ['eur', 'EUR'], ['euro', 'EUR'], ['€', 'EUR'], ['gbp', 'GBP'], ['sterlin', 'GBP'], ['sterling', 'GBP'], ['pound', 'GBP'], ['£', 'GBP']]
CURRENCIES = ['TRY', 'USD', 'EUR', 'GBP']
LABELS = dict([('TRY', 'Türk lirası'), ('USD', 'ABD doları'), ('EUR', 'Euro'), ('GBP', 'İngiliz sterlini')])
TOOL_NAME = 'voice_v1_cards_balance'
LIST_TOOL_NAME = 'voice_v1_cards_list'
DUE_WORDS = ['lastpaydate', 'lastpaymentdate', 'sonodemetarihi', 'sonodeme', 'sonödeme', 'sontarih', 'sontarıh', 'odemetarihi', 'ödemetarihi', 'duedate', 'due_date', 'paymentdue', 'payby', 'paydate', 'duetarihi', 'duetarıh', 'odemegunu', 'ödemegünü', 'son_odeme', 'sonOdemeTarihi', 'due', 'vade']
CUT_WORDS = ['statementdate', 'ekstretarihi', 'ekstretarıh', 'cutoffdate', 'cutoff', 'cut_off', 'hesapkesim', 'kesimtarihi', 'kesimtarıh', 'cutoffday', 'kesimgunu', 'kesimgünü', 'donemkesim', 'dönemkesim', 'kesimgunu']
CARD_WORDS = ['productname', 'cardname', 'kartadi', 'kartadı', 'cardholder', 'urunadi', 'ürünadı', 'card', 'kart', 'name', 'adi', 'adı']
NO_CARD_WORDS = ['nocard', 'kartyok', 'kartıyok', 'notfound', 'bulunamadi', 'bulunamadı', 'nocustomer', 'musteriyok', 'müşteriyok']
AVOID = ('next', 'sonraki', 'gelecek', 'previous', 'onceki', 'önceki')

PRIO = (('statementdebt', 100), ('ekstreborcu', 100), ('statementdebtamount', 100),
        ('totaldebt', 90), ('toplamborc', 90), ('remainingdebt', 80), ('kalanborc', 80),
        ('minpayment', 70), ('minimumodeme', 70), ('minimumödeme', 70),
        ('currentperiodexpense', 20), ('transferamount', 10), ('remainautomatic', 5))

def _prio(k):
    for word, p in PRIO:
        if word in k:
            return p
    return 50

# Every variable this node publishes is written up front, so a prompt can never
# reference something the node failed to produce.
vars['statement_text'] = 'Ekstre kaydı bulunamadı.'
vars['statement_card'] = ''
vars['statement_card_count'] = '0'
vars['statement_cards_text'] = ''
vars['statement_cutoff'] = ''
vars['statement_due'] = ''
vars['statement_missing'] = ''
vars['statement_ready'] = 'no'
vars['has_debt'] = 'unknown'
vars['statement_debt_state'] = 'unknown'
vars['statement_error_text'] = ''
vars['statement_min_tl'] = ''
vars['statement_remaining_tl'] = ''
for _c in CURRENCIES:
    vars['statement_' + _c.lower()] = ''
vars['statement_tl'] = ''

def _curcode(v):
    t = _s(v).lower().replace(' ', '')
    if not t or len(t) > 12:
        return ''
    for word, code in CUR_CODES:
        if word and (t == word or (len(word) > 2 and word in t)):
            return code
    return ''

def _as_obj(v):
    if isinstance(v, dict):
        return v
    if isinstance(v, (list, tuple)):
        return {'items': list(v)}
    if isinstance(v, str):
        t = v.strip()
        if t[:1] in ('{', '['):
            try:
                return json.loads(t)
            except Exception:
                return None
    return None

def _pick_body(name):
    if not name:
        return None
    return _as_obj(vars.get(name + '_response.data'))

def _flat_pairs(name):
    # a result may be flattened into dotted variable names instead of a dict
    out = []
    if not name:
        return out
    pre = name + '_response.data.'
    try:
        for _k in list(vars.keys()):
            ks = str(_k)
            if ks.startswith(pre):
                out.append((ks[len(pre):].lower(), vars.get(_k)))
    except Exception:
        pass
    return out

data = _pick_body(TOOL_NAME)
if data is None:
    data = _as_obj(vars.get('statement_data'))
if data is None:
    _best = None
    try:
        for _k in sorted(vars.keys()):
            if _k.endswith('_response.data') and isinstance(vars.get(_k), dict):
                _blob = str(vars.get(_k)).lower()
                if 'debt' in _blob or 'borc' in _blob or 'paydate' in _blob or 'balance' in _blob:
                    _best = vars.get(_k)
                    break
    except Exception:
        _best = None
    data = _best
if not isinstance(data, dict):
    data = {}

cards_body = _pick_body(LIST_TOOL_NAME)
if not isinstance(cards_body, dict):
    cards_body = _as_obj(vars.get('statement_cards'))
if not isinstance(cards_body, dict):
    cards_body = {}

pairs = []
try:
    _walk(data, '', pairs)
    if cards_body:
        _walk(cards_body, '', pairs)
    pairs.extend(_flat_pairs(TOOL_NAME))
    pairs.extend(_flat_pairs(LIST_TOOL_NAME))
except Exception:
    pairs = pairs or []

blocks = []
try:
    _dicts(data, blocks)
    if cards_body:
        _dicts(cards_body, blocks)
except Exception:
    blocks = blocks or []

def _first(words, avoid=AVOID):
    allow = False
    while True:
        for k, v in pairs:
            if not allow and any(a in k for a in avoid):
                continue
            for w in words:
                if w and w in k and _s(v):
                    return _s(v)
        if allow:
            return ''
        allow = True

def _date_text(raw):
    t = _s(raw)
    if not t:
        return ''
    m = re.match(r'^(\d{4})-(\d{2})-(\d{2})', t)
    if m:
        return m.group(3) + '.' + m.group(2) + '.' + m.group(1)
    return t

def _err_text(obj):
    try:
        for b in _dicts_of(obj):
            r = b.get('result') if isinstance(b.get('result'), dict) else b
            if not isinstance(r, dict):
                continue
            for k in ('messageText', 'message', 'errorMessage'):
                t = _s(r.get(k))
                if t and t.lower() not in ('success', 'ok'):
                    return t
    except Exception:
        return ''
    return ''

amounts = {}
mins = {}
remaining = {}
statuses = {}
for k, v in pairs:
    if 'paymentstatus' in k:
        t = _s(v).upper()
        if t:
            for word, code in CUR_CODES:
                if word and word in k:
                    if code not in statuses:
                        statuses[code] = t
                    break
    n = _num(v)
    if n is None:
        continue
    if any(a in k for a in AVOID):
        continue
    for word, code in CUR_CODES:
        if word and word in k:
            p = _prio(k)
            if 'minpayment' in k or 'minimumodeme' in k or 'minimumödeme' in k:
                if code not in mins or p > mins[code][0]:
                    mins[code] = (p, v)
            elif 'remaining' in k or 'kalan' in k:
                if code not in remaining or p > remaining[code][0]:
                    remaining[code] = (p, v)
            else:
                if code not in amounts or p > amounts[code][0]:
                    amounts[code] = (p, v)
            break

# a body that carries the currency in a value instead of a key
for b in blocks:
    cur = ''
    amt = None
    try:
        for k in b:
            vv = b[k]
            c = _curcode(vv)
            if c and not cur:
                cur = c
                continue
            if amt is None and _num(vv) is not None:
                amt = vv
    except Exception:
        continue
    if cur and amt is not None and cur not in amounts:
        amounts[cur] = (50, amt)

due = _date_text(_first(DUE_WORDS))
cut = _date_text(_first(CUT_WORDS))

def _cards_from(obj):
    out = []
    if not isinstance(obj, dict):
        return out
    try:
        for b in _dicts_of(obj):
            keys = {}
            for k in b:
                keys[str(k).lower()] = k
            num = ''
            for kk in keys:
                if 'cardnumber' in kk or kk in ('pan', 'maskedpan'):
                    num = _s(b[keys[kk]])
                    if num:
                        break
            if not num:
                continue
            nm = ''
            for kk in keys:
                if 'productname' in kk or 'cardname' in kk or 'kartadi' in kk or 'kartadı' in kk:
                    nm = _s(b[keys[kk]])
                    break
            l4 = ''
            l6 = ''
            for kk in keys:
                if 'last4' in kk or 'son4' in kk:
                    t = re.sub(r'\D', '', _s(b[keys[kk]]))
                    if len(t) >= 4:
                        l4 = t[-4:]
                        break
            _t = re.sub(r'\D', '', num)
            if not l4 and len(_t) >= 4:
                l4 = _t[-4:]
            if len(_t) >= 6:
                l6 = _t[-6:]
            out.append({'name': nm, 'last4': l4, 'last6': l6, 'masked': num})
    except Exception:
        return out
    return out

def _count_field(obj):
    # cards.list publishes validCardsCount: the authoritative card count
    try:
        for b in _dicts_of(obj):
            for k in b:
                if str(k).lower() in ('validcardscount', 'cardcount', 'card_count', 'totalcount'):
                    n = _num(b[k])
                    if n is not None:
                        return int(n)
    except Exception:
        return None
    return None

def _digits(v, n):
    t = re.sub(r'\D', '', _s(v))
    return t[-n:] if len(t) >= n else ''

def _cards_from_flat(fps):
    # the engine may flatten a result into dotted leaf variables; group the
    # card fields of the same object path back together
    groups = {}
    fields = ('cardnumberlast4', 'cardnumber', 'productname', 'cardname', 'kartadi')
    for k, v in fps:
        for fname in fields:
            if k.endswith(fname):
                groups.setdefault(k[:len(k) - len(fname)], {})[fname] = v
                break
    out = []
    for base in sorted(groups):
        g = groups[base]
        num = _s(g.get('cardnumber') or '')
        l4 = _digits(g.get('cardnumberlast4'), 4) or _digits(num, 4)
        nm = _s(g.get('productname') or g.get('cardname') or g.get('kartadi') or '')
        if num or l4 or nm:
            out.append({'name': nm, 'last4': l4, 'last6': _digits(num, 6), 'masked': num})
    return out

cards_in_data = _cards_from(data) or _cards_from_flat(_flat_pairs(TOOL_NAME))
cards_in_list = _cards_from(cards_body) or _cards_from_flat(_flat_pairs(LIST_TOOL_NAME))
# the card LIST is the authoritative roster; the balance result is one card
all_cards = cards_in_list if cards_in_list else cards_in_data

def _dup(c):
    n = 0
    for x in all_cards:
        if ((x.get('name') or '') == (c.get('name') or '')
                and (x.get('last4') or '') == (c.get('last4') or '')):
            n += 1
    return n > 1

def _card_label(c):
    if not c:
        return ''
    nm = c.get('name') or ''
    if _dup(c):
        ref = c.get('masked') or c.get('last6') or c.get('last4') or ''
    else:
        ref = c.get('last4') or c.get('masked') or ''
    if nm and ref:
        return nm + ' (' + ref + ')'
    return nm or c.get('masked') or ''

sel = None
if cards_in_data:
    sel = cards_in_data[0]
elif len(all_cards) == 1:
    sel = all_cards[0]

card = _card_label(sel)
_count = _count_field(cards_body)
card_count = str(_count) if _count is not None else str(len(all_cards))
cards_text = ''
if all_cards:
    cards_text = 'Kartlar: ' + ', '.join(x for x in (_card_label(c) for c in all_cards) if x)

err = _err_text(data) or _err_text(cards_body)

any_debt = False
for _code in amounts:
    _n = _num(amounts[_code][1])
    if _n is not None and _n > 0 and statuses.get(_code, '') != 'NO_DEBT':
        any_debt = True

saw_debt = bool(amounts)
if not saw_debt:
    for k, v in pairs:
        if 'debt' in k or 'borc' in k or 'bakiye' in k or 'balance' in k:
            saw_debt = True
            break

if any_debt:
    state = 'has'
elif saw_debt:
    state = 'none'
elif all_cards:
    state = 'no_card_data'
elif err:
    state = 'no_card' if ('kart' in err.lower() or 'card' in err.lower()) else 'error'
else:
    state = 'unknown'

missing = []
for _code in CURRENCIES:
    if _code not in amounts:
        missing.append(LABELS.get(_code, _code) + ' (' + _code + ')')

parts = []
if card:
    parts.append('Kart: ' + card)
if state == 'has':
    for _code in CURRENCIES:
        if _code in amounts:
            value = _fmt(amounts[_code][1])
            _n2 = _num(amounts[_code][1])
            if statuses.get(_code, '') == 'NO_DEBT' and (_n2 is None or _n2 <= 0):
                parts.append(LABELS.get(_code, _code) + ': borç yok')
            elif value:
                parts.append(LABELS.get(_code, _code) + ': ' + value + ' ' + _code)
    if due:
        parts.append('Son ödeme tarihi: ' + due)
    if cut:
        parts.append('Hesap kesim tarihi: ' + cut)
elif state == 'none':
    parts.append('Ekstre borcu yok: kayıtlarda borç görünmüyor.')
    if due:
        parts.append('Son ödeme tarihi: ' + due)
    if cut:
        parts.append('Hesap kesim tarihi: ' + cut)
elif state == 'no_card_data':
    parts.append('Kart listesi alındı; ekstre borcu için kartın seçilmesi gerekiyor.')
elif err:
    parts.append(err)
else:
    parts.append('Ekstre kaydı bulunamadı.')

vars['statement_text'] = ' | '.join(parts)
vars['statement_card'] = card
vars['statement_card_count'] = card_count
vars['statement_cards_text'] = cards_text
vars['statement_cutoff'] = cut
vars['statement_due'] = due
vars['statement_ready'] = 'yes' if (data or cards_body) else 'no'
vars['has_debt'] = ('yes' if state == 'has' else ('no' if state == 'none' else 'unknown'))
vars['statement_debt_state'] = state
vars['statement_error_text'] = err
vars['statement_missing'] = (', '.join(missing) if missing else '')
if 'TRY' in mins:
    vars['statement_min_tl'] = _fmt(mins['TRY'][1])
if 'TRY' in remaining:
    _rem = _fmt(remaining['TRY'][1])
    if 'TRY' not in amounts or _s(remaining['TRY'][1]) != _s(amounts['TRY'][1]):
        vars['statement_remaining_tl'] = _rem
for _code in CURRENCIES:
    vars['statement_' + _code.lower()] = (_fmt(amounts[_code][1]) if _code in amounts else '')
# statement_try (TRY) is also published as statement_tl: the prompt's TL slot
if 'TRY' in amounts:
    vars['statement_tl'] = _fmt(amounts['TRY'][1])

tools.pre_process_code:
try:
    _ALLOWED = {'Main menu': ['No eligible card', 'Nothing else wanted', 'Three tries used up', 'Wants another transaction mid-flow', 'Question outside this step', 'caller agrees to go', 'Not speaking Turkish', 'E-mail sent / declined', 'statement week changed / declined', 'Question outside this step, caller agrees to go', 'E-mail sent / declined, statement week changed / declined'], 'Call closed': ['Third silence'], 'Agent': ['Wants to pay / asks how or where to pay', 'Asks for an agent', 'Dispute / payment not showing', 'Still complaining after three calming replies', 'Card list or balance service fails', 'E-mail services fail', 'Statement week services fail'], 'IVR login step': ["Asking about someone else's card"]}
    _NO_REASON = ['promise', 'paid']
    _PROMISE_WINS = True
    _TRANSFER_WINS = False
    _TRANSFER_QUEUES = []
    _QUEUE_REASONS = {}
    _PAID_ALL = True
    _NOTES_OUTCOME = 'no_promise'

    def _s(v):
        return '' if v is None else str(v).strip()

    def _lc(v):
        return _s(v).lower()

    def _num(v):
        try:
            s = _s(v)
            return int(float(s)) if s else 0
        except Exception:
            return 0

    def _true(v):
        return _lc(v) in ('true', '1', 'yes', 'evet', 'ok', 'success')

    def _allowed(o):
        return [str(x) for x in (_ALLOWED.get(o) or [])]

    def _pair_ok(o, r):
        if o not in _ALLOWED:
            return False
        rs = _allowed(o)
        rl = _lc(r)
        if not rs:
            return rl in ('', 'none', 'null')
        return rl in [x.lower() for x in rs]

    def _pick(o, *prefs):
        rs = _allowed(o)
        for p in prefs:
            pl = _lc(p)
            for r in rs:
                if r.lower() == pl:
                    return r
        return rs[0] if len(rs) == 1 else None

    def _put(o, r):
        if not _pair_ok(o, r):
            return False
        b = config.get('body')
        if not isinstance(b, dict):
            b = {}
            config['body'] = b
        b['outcome'] = o
        if o in _NO_REASON or not _lc(r):
            b.pop('reason', None)
        else:
            b['reason'] = r
        return True

    def _notes():
        out = []
        seq = _s(vars.get('notes_seq'))
        if seq:
            for part in seq.split('|'):
                part = part.strip().lower()
                if part:
                    out.append(part)
        if not out:
            r = _lc(vars.get('add_note_args.reason'))
            if r:
                out.append(r)
        return out

    def _first_note(notes):
        for n in notes:
            if n != 'paid':
                return n
        return notes[0] if notes else None

    promised = _num(vars.get('create_promise_success_count')) > 0
    transfers = _num(vars.get('transfer_to_human_success_count'))
    queue = _s(vars.get('transfer_to_human_args.queue'))
    qlow = queue.lower()
    verified = (_true(vars.get('verify_identity_response.data.all_verified'))
                or _true(vars.get('verify_identity_response.data.verified')))
    wrong_left = _lc(vars.get('verify_identity_response.data.wrong_answers_left'))
    notes = _notes()

    def _transfer_reason():
        rs = _allowed('transferred')
        if not rs:
            return None
        mapped = _QUEUE_REASONS.get(qlow)
        if mapped and _lc(mapped) in [r.lower() for r in rs]:
            return mapped
        for r in rs:
            if r.lower() == qlow:
                return r
        return _pick('transferred')

    transfer_wins = transfers > 0 and (_TRANSFER_WINS or (qlow and qlow in [str(q).lower() for q in _TRANSFER_QUEUES]))
    done = False
    if promised and transfer_wins:
        done = _put('transferred', _transfer_reason())
    if not done and promised and _PROMISE_WINS:
        done = _put('promise', None)
    if not done and transfers > 0:
        done = _put('transferred', _transfer_reason())
    if not done and notes and _PAID_ALL and all(n == 'paid' for n in notes):
        done = _put('paid', None)
    if not done and notes:
        first = _first_note(notes)
        done = _put(_NOTES_OUTCOME, _pick(_NOTES_OUTCOME, first)) or _put(_NOTES_OUTCOME, first)
    if not done and not verified and wrong_left in ('0', '0.0'):
        done = _put('not_verified', _pick('not_verified', 'failed'))
    if not done and not verified and (_true(vars.get('identity_declined')) or _true(vars.get('declined'))):
        done = _put('not_verified', _pick('not_verified', 'declined'))
    if not done and ((_lc(vars.get('who_answers')) == 'deceased') or _true(vars.get('is_deceased')) or _true(vars.get('deceased')) or _lc(vars.get('situation')) == 'deceased'):
        done = _put('not_reached', _pick('not_reached', 'deceased'))
    if not done and ((_lc(vars.get('who_answers')) == 'wrong_number') or _true(vars.get('is_wrong_number')) or _true(vars.get('wrong_number')) or _lc(vars.get('situation')) == 'wrong_number'):
        done = _put('not_reached', _pick('not_reached', 'wrong_number'))
    if not done and _num(vars.get('schedule_callback_success_count')) > 0:
        done = _put('not_reached', _pick('not_reached', 'callback'))
    if not done and (_true(vars.get('callback_declined')) or _true(vars.get('no_callback')) or _lc(vars.get('situation')) == 'callback_refused'):
        done = _put('not_reached', _pick('not_reached', 'no_callback'))
    b = config.get('body')
    if isinstance(b, dict):
        o = _lc(b.get('outcome'))
        if o in _NO_REASON:
            b.pop('reason', None)
        elif o in _ALLOWED:
            rs = _allowed(o)
            if len(rs) == 1 and _lc(b.get('reason')) != _lc(rs[0]):
                b['reason'] = rs[0]
except Exception:
    pass
